import redis

class Cache:
    def __init__(self, url: str, ttl: int = 3600):
        self.client = redis.from_url(url)
        self.ttl = ttl

    def get(self, key: str):
        return self.client.get(key)

    def set(self, key: str, value: str):
        self.client.setex(key, self.ttl, value)

